import torch, b200probe as P
src = r'''
extern "C" __global__ void k_tanh(const float* __restrict__ x, float* __restrict__ y, long long rows) {
  long long o = (long long)blockIdx.x * blockDim.x + threadIdx.x;  // chunk of 8
  long long n = rows * 640;
  if (o >= n) return;
  long long row = o / 640, col = o - row * 640;
  const float* g = x + row * 10240 + col * 8;
  const float* l = g + 5120;
  float gv[8], lv[8], ov[8];
  asm volatile("ld.global.nc.v8.f32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];" : "=f"(gv[0]),"=f"(gv[1]),"=f"(gv[2]),"=f"(gv[3]),"=f"(gv[4]),"=f"(gv[5]),"=f"(gv[6]),"=f"(gv[7]) : "l"(g));
  asm volatile("ld.global.nc.v8.f32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];" : "=f"(lv[0]),"=f"(lv[1]),"=f"(lv[2]),"=f"(lv[3]),"=f"(lv[4]),"=f"(lv[5]),"=f"(lv[6]),"=f"(lv[7]) : "l"(l));
  #pragma unroll
  for (int i = 0; i < 8; ++i) {
    float a = gv[i];
    float u = 0.7978845608028654f * (a + 0.044715f * a * a * a);
    ov[i] = 0.5f * a * (1.f + tanhf(u)) * lv[i];
  }
  float* q = y + row * 5120 + col * 8;
  asm volatile("st.global.v8.f32 [%0], {%1,%2,%3,%4,%5,%6,%7,%8};" :: "l"(q), "f"(ov[0]),"f"(ov[1]),"f"(ov[2]),"f"(ov[3]),"f"(ov[4]),"f"(ov[5]),"f"(ov[6]),"f"(ov[7]) : "memory");
}
extern "C" __global__ void k_sig(const float* __restrict__ x, float* __restrict__ y, long long rows) {
  long long o = (long long)blockIdx.x * blockDim.x + threadIdx.x;
  long long n = rows * 640;
  if (o >= n) return;
  long long row = o / 640, col = o - row * 640;
  const float* g = x + row * 10240 + col * 8;
  const float* l = g + 5120;
  float gv[8], lv[8], ov[8];
  asm volatile("ld.global.nc.v8.f32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];" : "=f"(gv[0]),"=f"(gv[1]),"=f"(gv[2]),"=f"(gv[3]),"=f"(gv[4]),"=f"(gv[5]),"=f"(gv[6]),"=f"(gv[7]) : "l"(g));
  asm volatile("ld.global.nc.v8.f32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];" : "=f"(lv[0]),"=f"(lv[1]),"=f"(lv[2]),"=f"(lv[3]),"=f"(lv[4]),"=f"(lv[5]),"=f"(lv[6]),"=f"(lv[7]) : "l"(l));
  #pragma unroll
  for (int i = 0; i < 8; ++i) {
    float a = gv[i];
    float u2 = 1.5957691216057308f * (a + 0.044715f * a * a * a);   // 2*sqrt(2/pi)*(...)
    float e = __expf(-u2);
    ov[i] = a * lv[i] * __fdividef(1.f, 1.f + e);
  }
  float* q = y + row * 5120 + col * 8;
  asm volatile("st.global.v8.f32 [%0], {%1,%2,%3,%4,%5,%6,%7,%8};" :: "l"(q), "f"(ov[0]),"f"(ov[1]),"f"(ov[2]),"f"(ov[3]),"f"(ov[4]),"f"(ov[5]),"f"(ov[6]),"f"(ov[7]) : "memory");
}
'''
for opts in [(), ('--use_fast_math',)]:
    kt = P.cuda_kernel(src, 'k_tanh', opts); ks = P.cuda_kernel(src, 'k_sig', opts)
    print(opts, P.resources(src, opts))
    for rows in [128, 2048]:
        x = torch.randn(rows, 10240, device='cuda')
        xg, xl = x.chunk(2, -1)
        ref = torch.nn.functional.gelu(xg, approximate='tanh') * xl
        for nm, k in [('tanh', kt), ('sig', ks)]:
            y = torch.zeros(rows, 5120, device='cuda')
            n = rows * 640
            k(((n + 255)//256,), (256,), x, y, n and rows)
            torch.cuda.synchronize()
            err = (y - ref).abs(); tol = 1e-5 + 1e-5 * ref.abs()
            bad = (err > tol).float().mean().item()
            rel = (err / (ref.abs() + 1e-30))
            print(f'{opts} rows={rows} {nm}: max_abs={err.max().item():.3e} bad_frac={bad:.2e} maxrel(|ref|>1e-3)={rel[ref.abs()>1e-3].max().item():.3e} nan={torch.isnan(y).any().item()}')
# timing at a few sizes with fast math sig kernel
ks = P.cuda_kernel(src, 'k_sig', ('--use_fast_math',))
kt = P.cuda_kernel(src, 'k_tanh', ('--use_fast_math',))
def mk(k):
    def fn(x, y):
        rows = x.shape[0]; n = rows * 640
        k(((n + 255)//256,), (256,), x, y, rows)
    return fn
for rows in [128, 512, 1024, 2048, 4096, 8192]:
    x = torch.randn(rows, 10240, device='cuda'); y = torch.empty(rows, 5120, device='cuda')
    ts = P.harness_time(mk(ks), (x,), (y,)); tt = P.harness_time(mk(kt), (x,), (y,))
    mb = rows*5120*12/1e6
    print(f'rows={rows} {mb:.1f}MB sig {ts:.2f}us ({mb/ts/1e6*1e6/1e6:.2f} TB/s)  tanh {tt:.2f}us')

