  ld8(g + INNER, lv);
  unsigned long long pol;
  asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;" : "=l"(pol));
#pragma unroll
  for (int i = 0; i < 8; ++i) ov[i] = geglu(gv[i], lv[i]);
  st8_el(y + row * INNER + col, ov, pol);
